def generate_numbers(sum_dig: int, digs: int) -> list:
    if sum_dig < digs or sum_dig > 9 * digs:
        return []

    def is_valid_number(num: int, sum_dig: int) -> bool:
        digits = [int(d) for d in str(num)]
        return sum(digits) == sum_dig and all(digits[i] <= digits[i + 1] for i in range(len(digits) - 1))

    numbers = []
    for num in range(10**(digs-1), 10**digs):
        if is_valid_number(num, sum_dig):
            numbers.append(num)

    if not numbers:
        return []

    return [len(numbers), min(numbers), max(numbers)]
