def simplify(poly: str) -> str:
    from collections import defaultdict

    def combine_like_terms(sorted_monomials: dict) -> dict:
        combined = defaultdict(int)
        for term, coeff in sorted_monomials.items():
            combined[term] += coeff
        return {term: coeff for term, coeff in combined.items() if coeff != 0}

    def sort_monomials(monomials: list) -> list:
        return sorted(monomials, key=lambda x: (len(x), x))

    def parse_polynomial(poly: str) -> dict:
        terms = poly.split('+')
        monomials = []
        for term in terms:
            if '-' in term:
                term = term.replace('-', '+-')
                terms = term.split('+')
                for t in terms:
                    if t:
                        monomials.append(t)
            else:
                monomials.append(term)
        parsed_monomials = {}
        for monomial in monomials:
            if monomial:
                coeff, term = monomial.split('x') if 'x' in monomial else (monomial, '')
                coeff = int(coeff) if coeff else 1
                sorted_term = ''.join(sorted(term))
                parsed_monomials[sorted_term] = parsed_monomials.get(sorted_term, 0) + coeff
        return parsed_monomials

    monomials = parse_polynomial(poly)
    sorted_monomials = sort_monomials(list(monomials.keys()))
    combined_monomials = combine_like_terms(dict(zip(sorted_monomials, monomials.values())))
    simplified_poly = '+'.join(f"{coeff}{'x' + term if term else ''}" for term, coeff in combined_monomials.items())
    return simplified_poly.lstrip('+')
