def simplify(poly: str) -> str:
    from collections import defaultdict

    def combine_like_terms(sorted_monomials: dict) -> dict:
        combined = defaultdict(int)
        for monomial, coeff in sorted_monomials.items():
            combined[monomial] += coeff
        return {monomial: coeff for monomial, coeff in combined.items() if coeff != 0}

    def parse_monomial(monomial: str) -> (dict, int):
        if monomial.startswith('-'):
            coeff = -1
            monomial = monomial[1:]
        elif monomial.startswith('+'):
            coeff = 1
            monomial = monomial[1:]
        else:
            coeff = 1

        if not monomial:
            return {}, coeff

        variables = {}
        i = 0
        while i < len(monomial):
            if monomial[i] in 'abcdefghijklmnopqrstuvwxyz':
                j = i + 1
                while j < len(monomial) and monomial[j] in 'abcdefghijklmnopqrstuvwxyz':
                    j += 1
                variables[monomial[i:j]] = 1
                i = j
            elif monomial[i] == 'x':
                i += 1
            elif monomial[i] == 'y':
                i += 1
            elif monomial[i] == 'z':
                i += 1
            else:
                raise ValueError(f"Invalid monomial: {monomial}")
        return variables, coeff

    def sort_monomials(monomials: list) -> list:
        return sorted(monomials, key=lambda x: (len(x), x))

    monomials = poly.split('+')
    parsed_monomials = []
    for monomial in monomials:
        variables, coeff = parse_monomial(monomial)
        parsed_monomials.append((variables, coeff))

    sorted_monomials = {}
    for variables, coeff in parsed_monomials:
        monomial = ''.join(sorted(variables.keys()))
        if monomial in sorted_monomials:
            sorted_monomials[monomial] += coeff
        else:
            sorted_monomials[monomial] = coeff

    combined_monomials = combine_like_terms(sorted_monomials)
    result = []
    for monomial, coeff in sorted(combined_monomials.items()):
        if coeff == 1:
            result.append(monomial)
        elif coeff == -1:
            result.append(f'-{monomial}')
        else:
            result.append(f'{coeff}{monomial}')

    return '+'.join(result)
