from typing import List

def amazon_check_mate(king: str, amazon: str) -> List[int]:
    def is_valid_position(position: str) -> bool:
        return position[0] in 'ABCDEFGH' and position[1] in '12345678'

    def is_adjacent(pos1: str, pos2: str) -> bool:
        return abs(ord(pos1[0]) - ord(pos2[0])) <= 1 and abs(int(pos1[1]) - int(pos2[1])) <= 1

    def get_amazon_moves(amazon: str) -> set:
        moves = set()
        for i in range(8):
            for j in range(8):
                pos = chr(97 + i) + str(j + 1)
                if is_adjacent(amazon, pos):
                    moves.add(pos)
        return moves

    def is_safe_position(position: str) -> bool:
        return not any(is_adjacent(position, move) for move in get_amazon_moves(amazon))

    def is_checkmate_position(position: str) -> bool:
        return is_adjacent(position, amazon) and not any(is_adjacent(move, position) for move in get_amazon_moves(king))

    def is_check_position(position: str) -> bool:
        return is_adjacent(position, amazon) and any(is_adjacent(move, position) for move in get_amazon_moves(king))

    def is_stalemate_position(position: str) -> bool:
        return is_safe_position(position) and not any(is_adjacent(move, position) for move in get_amazon_moves(king))

    checkmate_count = sum(is_checkmate_position(chr(i) + str(j)) for i in range(8) for j in range(8))
    check_count = sum(is_check_position(chr(i) + str(j)) for i in range(8) for j in range(8))
    stalemate_count = sum(is_stalemate_position(chr(i) + str(j)) for i in range(8) for j in range(8))
    safe_count = sum(is_safe_position(chr(i) + str(j)) for i in range(8) for j in range(8))

    return [checkmate_count, check_count, stalemate_count, safe_count]
